def sum_of_divisors(n):
    n = abs(n)
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i * i != n:
                total += n // i
        i += 1
    return total

def proper_divisors(n):
    n = abs(n)
    return [i for i in range(1, n) if n % i == 0]

def are_amicable(a, b):
    def spd(n):
        return sum(i for i in range(1, n) if n % i == 0)
    return a != b and spd(a) == b and spd(b) == a

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def binomial_coefficient(n, r):
    if r < 0 or r > n:
        return 0
    r = min(r, n - r)
    num = 1
    den = 1
    for i in range(r):
        num *= (n - i)
        den *= (i + 1)
    return num // den

def integer_sqrt(n):
    import math
    return math.isqrt(n)

def is_perfect_square(n):
    import math
    if n < 0:
        return False
    r = math.isqrt(n)
    return r * r == n

def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = vals[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

def next_power_of_two(n):
    p = 1
    while p < n:
        p *= 2
    return p

def digital_root(n):
    n = abs(n)
    if n == 0:
        return 0
    return 1 + (n - 1) % 9

def is_armstrong_number(n):
    if n < 0:
        return False
    s = str(n)
    p = len(s)
    return n == sum(int(d) ** p for d in s)

def is_happy_number(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d) ** 2 for d in str(n))
    return n == 1

def extended_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return (old_r, old_s, old_t)
